#include "r19_model.hpp"
V6Archive encode19(const Games&games,unsigned mode,const Table19&t,MidDiagnostics*diag=nullptr,std::ostream*examples=nullptr){
 if(mode>4||games.size()>100000)fail("mode/count18");bool active=std::any_of(t.begin(),t.end(),[](int v){return v!=0;});if(diag)*diag={};Context18 c;ArithmeticEncoder coder;uint64_t total=0;
 for(const auto&g:games){if(g.size()>1000000||(total+=g.size())>300000000)fail("length18");Position p=Position::standard();Move prev{},own[2]{};bool hp=false,ho[2]={};for(unsigned ply=0;ply<g.size();++ply){unsigned stage=V7Patterns::phase(p,ply),side=p.side;auto s=step19(p,hp?&prev:nullptr,ho[side]?&own[side]:nullptr,ply,stage,c,mode,t,active);unsigned ix=index_of(s.base.moves,g[ply]);
  if(examples&&stage==1){auto z=base19(p,hp?&prev:nullptr,ho[side]?&own[side]:nullptr,ply,c);auto put=[&](unsigned v){examples->put(char(v));examples->put(char(v>>8));};put(z.base.moves.size);put(ix);for(unsigned i=0;i<z.base.moves.size;++i){put(z.coded.weights[i]);for(auto k:z.r12_features[i])put(168*bucket18(z.base.flags[i])+k);unsigned piece=unsigned(abs_piece(p.board[z.base.moves.a[i].m.from])-1);put(response19(z.base.flags[i],piece));put(direct19(z.base.moves.a[i].m.to,piece));}}
  mid_record(diag,stage,s,ix);coder.put(v6_before(s.coded,ix),s.coded.weights[ix],s.coded.total);observe19(c,p,s,ix,ply,stage,mode);p.apply_unchecked(g[ply]);own[side]=g[ply];ho[side]=true;prev=g[ply];hp=true;
 }}auto payload=total?coder.finish():EntropyPayload{};std::vector<uint8_t>b={'D','1','9','P',1,uint8_t(mode)};auto id=id19(t);for(int k=0;k<4;++k)b.push_back(uint8_t(id>>(8*k)));v6_varint(b,uint32_t(games.size()));for(auto&g:games)v6_varint(b,uint32_t(g.size()));v6_varint(b,payload.bit_count);uint64_t framing=b.size()+4;b.insert(b.end(),payload.bytes.begin(),payload.bytes.end());auto crc=v6_crc(b.data(),b.size());for(int k=0;k<4;++k)b.push_back(uint8_t(crc>>(8*k)));return {std::move(b),payload.bit_count,framing};
}
Games decode19(const std::vector<uint8_t>&b,const Table19&t){
 if(b.size()<16||std::string(b.begin(),b.begin()+4)!="D19P"||b[4]!=1||b[5]>4)fail("header18");uint32_t crc=0,id=0;for(int k=0;k<4;++k){crc|=uint32_t(b[b.size()-4+k])<<(8*k);id|=uint32_t(b[6+k])<<(8*k);}if(crc!=v6_crc(b.data(),b.size()-4)||id!=id19(t))fail("CRC/model18");size_t off=10;unsigned count=v6_unvar(b,off);if(count>100000)fail("count18");std::vector<uint32_t>lens;uint64_t total=0;for(unsigned j=0;j<count;++j){auto n=v6_unvar(b,off);if(n>1000000||(total+=n)>300000000)fail("length18");lens.push_back(n);}auto bits=v6_unvar(b,off);if(off+4>b.size()||(uint64_t(bits)+7)/8!=b.size()-off-4||(total&&!bits))fail("payload19");ArithmeticDecoder coder(b.data()+off,bits);Context18 c;Games games;bool active=std::any_of(t.begin(),t.end(),[](int v){return v!=0;});
 for(auto len:lens){Position p=Position::standard();Move prev{},own[2]{};bool hp=false,ho[2]={};std::vector<Move>g;for(unsigned ply=0;ply<len;++ply){unsigned stage=V7Patterns::phase(p,ply),side=p.side;auto s=step19(p,hp?&prev:nullptr,ho[side]?&own[side]:nullptr,ply,stage,c,b[5],t,active);uint32_t before=0;auto ix=v6_select(s.coded,s.base.moves.size,coder.target(s.coded.total),before);coder.take(before,s.coded.weights[ix],s.coded.total);auto m=s.base.moves.a[ix].m;observe19(c,p,s,ix,ply,stage,b[5]);p.apply_unchecked(m);own[side]=m;ho[side]=true;prev=m;hp=true;g.push_back(m);}games.push_back(std::move(g));}return games;
}
int main(int argc,char**argv){try{if(argc!=2)fail("bundle");auto games=read_games(argv[1]);auto table=load19("builtin");auto a=encode19(games,0,table),b=encode19(games,3,table);if(decode19(a.bytes,table)!=games||decode19(b.bytes,table)!=games)fail("warm");uint64_t plies=0;for(auto&g:games)plies+=g.size();std::cout<<"round,direction,slot,mode,plies,wall_seconds,cpu_seconds\n"<<std::setprecision(12);
for(unsigned round=0;round<8;++round){for(unsigned direction=0;direction<2;++direction){std::array<unsigned,4>order= (round+direction)%2?std::array<unsigned,4>{3,0,0,3}:std::array<unsigned,4>{0,3,3,0};for(unsigned slot=0;slot<4;++slot){unsigned mode=order[slot];auto w0=std::chrono::steady_clock::now();auto c0=std::clock();bool valid;if(direction==0){auto got=encode19(games,mode,table);auto c1=std::clock();auto w1=std::chrono::steady_clock::now();valid=got.bytes==(mode==0?a:b).bytes;std::cout<<round<<",encode,"<<slot<<','<<mode<<','<<plies<<','<<std::chrono::duration<double>(w1-w0).count()<<','<<double(c1-c0)/CLOCKS_PER_SEC<<'\n';}else{auto got=decode19((mode==0?a:b).bytes,table);auto c1=std::clock();auto w1=std::chrono::steady_clock::now();valid=got==games;std::cout<<round<<",decode,"<<slot<<','<<mode<<','<<plies<<','<<std::chrono::duration<double>(w1-w0).count()<<','<<double(c1-c0)/CLOCKS_PER_SEC<<'\n';}if(!valid)fail("pair mismatch");}std::cout<<std::flush;}std::cerr<<"paired "<<round+1<<"/8\n";}
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}return 0;}
